window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-a3d5c1d0d3bbf749"]={"versions": [{"id": "FIG-a3d5c1d0d3bbf749", "releases": ["R4.0.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (Objekt-/Instanzebene) des AUTOSAR-Netzwerkmanagement-Stacks für UDP. Das Diagramm stellt die Schichtenarchitektur innerhalb eines Steuergeräts (ECU) dar, das an zwei voneinander unabhängige UDP-NM-Cluster angebunden ist. Es gliedert sich in die übergeordnete Schicht des generischen Netzwerkmanagements (<code>Nm</code>), die bus- bzw. protokollspezifische Zwischenschicht (<code>UdpNm</code>) sowie die darunterliegende Socket-Adaptionsschicht (<code>SoAd</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert vier Software-Komponenteninstanzen (gekennzeichnet durch unterstrichene Instanznotation <code>:Typ</code> mit UML-Komponentensymbol):</p>\n<ul class=\"fig-list\"><li><code>:Nm</code>: Eine gemeinsame, übergeordnete Instanz des generischen AUTOSAR Network Management Interface (<code>Nm</code>), horizontal über die gesamte Breite aufgeteilt (grau hinterlegt).\n</li><li><code>:UdpNm</code>: Zwei nebeneinander platzierte, separate Instanzen des UDP-Netzwerkmanagements (<code>UdpNm</code>), die jeweils einem spezifischen UDP-NM-Cluster zugeordnet sind.\n</li><li><code>:SoAd</code>: Eine gemeinsame unterlagerte Instanz des Socket Adaptors (<code>SoAd</code>), horizontal über die gesamte Breite angeordnet.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen oder Port-Symbole sind nicht explizit als Konnektoren eingezeichnet; die Interaktion erfolgt implizit über die vertikale Schichtung (<code>:Nm</code> kommuniziert nach unten mit beiden <code>:UdpNm</code>-Instanzen, beide <code>:UdpNm</code>-Instanzen kommunizieren nach unten mit <code>:SoAd</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Instanzstruktur ohne Kontrollfluss-, Sequenz- oder Zeitinformationen. Aus der vertikalen Schichtung und Multi-Cluster-Konfiguration leitet sich folgendes Interaktionsmuster ab:</p>\n<ul class=\"fig-list\"><li>Zyklische NM-Nachrichten und Zustandstrigger des generischen <code>:Nm</code> werden clusterindividuell an die jeweils zuständige <code>:UdpNm</code>-Instanz weitergeleitet.\n</li><li>Beide <code>:UdpNm</code>-Instanzen steuern unabhängig voneinander das Senden und Empfangen von NM-Botschaften über Sockets der gemeinsamen <code>:SoAd</code>-Instanz.\n</li><li>Empfangene NM-Pakete aus <code>:SoAd</code> werden clusterbezogen der jeweiligen <code>:UdpNm</code>-Instanz zugestellt und an <code>:Nm</code> signalisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ veranschaulicht das Diagramm die Skalierungseinschränkung des UdpNm-Moduls:</p>\n<ul class=\"fig-list\"><li>Pro NM-Cluster und Netzwerk existiert auf dem Steuergerät genau eine <code>:UdpNm</code>-Instanz (1:1-Zuordnung je Cluster/Netzwerk).\n</li><li>Eine ECU, die an mehrere UDP-NM-Cluster angebunden ist, erfordert mehrere parallele Instanzen von <code>UdpNm</code>.\n</li><li>Alle <code>UdpNm</code>-Instanzen teilen sich eine gemeinsame <code>:Nm</code>-Instanz auf höherer Ebene und eine gemeinsame <code>:SoAd</code>-Instanz zur UDP-Kommunikation. Entwickler müssen bei Multi-Channel-/Multi-Cluster-Konfigurationen die Kanal- und Socket-Zuordnung in den BSW-Modulbeschreibungen strikt trennen.\n</li></ul>"}, {"id": "FIG-9a33df7b242c05e5", "releases": ["R4.1.3", "R4.2.2", "R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (Objekt-/Instanzebene) des AUTOSAR-Netzwerkmanagement-Stacks für UDP innerhalb eines äußeren Diagrammrahmens mit dem Bezeichner <code>id AUTOSAR NM Stack over UDP</code>. Das Diagramm stellt die Schichtenarchitektur innerhalb eines Steuergeräts (ECU) dar, das an zwei voneinander unabhängige UDP-NM-Cluster angebunden ist. Es gliedert sich in die übergeordnete Schicht des generischen Netzwerkmanagements (<code>Nm</code>), die bus- bzw. protokollspezifische Zwischenschicht (<code>UdpNm</code>) sowie die darunterliegende Socket-Adaptionsschicht (<code>SoAd</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert vier Software-Komponenteninstanzen (gekennzeichnet durch unterstrichene Instanznotation <code>:Typ</code> mit UML-Komponentensymbol):</p>\n<ul class=\"fig-list\"><li><code>:Nm</code>: Eine gemeinsame, übergeordnete Instanz des generischen AUTOSAR Network Management Interface (<code>Nm</code>), horizontal über die gesamte Breite aufgeteilt (grau hinterlegt).\n</li><li><code>:UdpNm</code>: Zwei nebeneinander platzierte, separate Instanzen des UDP-Netzwerkmanagements (<code>UdpNm</code>), die jeweils einem spezifischen UDP-NM-Cluster zugeordnet sind.\n</li><li><code>:SoAd</code>: Eine gemeinsame unterlagerte Instanz des Socket Adaptors (<code>SoAd</code>), horizontal über die gesamte Breite angeordnet.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen oder Port-Symbole sind nicht explizit als Konnektoren eingezeichnet; die Interaktion erfolgt implizit über die vertikale Schichtung (<code>:Nm</code> kommuniziert nach unten mit beiden <code>:UdpNm</code>-Instanzen, beide <code>:UdpNm</code>-Instanzen kommunizieren nach unten mit <code>:SoAd</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Instanzstruktur ohne Kontrollfluss-, Sequenz- oder Zeitinformationen. Aus der vertikalen Schichtung und Multi-Cluster-Konfiguration leitet sich folgendes Interaktionsmuster ab:</p>\n<ul class=\"fig-list\"><li>Zyklische NM-Nachrichten und Zustandstrigger des generischen <code>:Nm</code> werden clusterindividuell an die jeweils zuständige <code>:UdpNm</code>-Instanz weitergeleitet.\n</li><li>Beide <code>:UdpNm</code>-Instanzen steuern unabhängig voneinander das Senden und Empfangen von NM-Botschaften über Sockets der gemeinsamen <code>:SoAd</code>-Instanz.\n</li><li>Empfangene NM-Pakete aus <code>:SoAd</code> werden clusterbezogen der jeweiligen <code>:UdpNm</code>-Instanz zugestellt und an <code>:Nm</code> signalisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ veranschaulicht das Diagramm die Skalierungseinschränkung des UdpNm-Moduls:</p>\n<ul class=\"fig-list\"><li>Pro NM-Cluster und Netzwerk existiert auf dem Steuergerät genau eine <code>:UdpNm</code>-Instanz (1:1-Zuordnung je Cluster/Netzwerk).\n</li><li>Eine ECU, die an mehrere UDP-NM-Cluster angebunden ist, erfordert mehrere parallele Instanzen von <code>UdpNm</code>.\n</li><li>Alle <code>UdpNm</code>-Instanzen teilen sich eine gemeinsame <code>:Nm</code>-Instanz auf höherer Ebene und eine gemeinsame <code>:SoAd</code>-Instanz zur UDP-Kommunikation. Entwickler müssen bei Multi-Channel-/Multi-Cluster-Konfigurationen die Kanal- und Socket-Zuordnung in den BSW-Modulbeschreibungen strikt trennen.\n</li></ul>"}, {"id": "FIG-7c689f44b87ae3c1", "releases": ["R20-11", "R21-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">UML-Komponentendiagramm (Objekt-/Instanzebene) des AUTOSAR-Netzwerkmanagement-Stacks für UDP innerhalb eines äußeren Diagrammrahmens mit dem Bezeichner <code>id AUTOSAR NM Stack over UDP</code>. Das Diagramm stellt die Schichtenarchitektur innerhalb eines Steuergeräts (ECU) dar, das an zwei voneinander unabhängige UDP-NM-Cluster angebunden ist. Es gliedert sich in die übergeordnete Schicht des generischen Netzwerkmanagements (<code>Nm</code>), die bus- bzw. protokollspezifische Zwischenschicht (<code>UdpNm</code>) sowie die darunterliegende Socket-Adaptionsschicht (<code>SoAd</code>).</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm modelliert vier Software-Komponenteninstanzen (gekennzeichnet durch unterstrichene Instanznotation <code>:Typ</code> mit UML-Komponentensymbol):</p>\n<ul class=\"fig-list\"><li><code>:Nm</code>: Eine gemeinsame, übergeordnete Instanz des generischen AUTOSAR Network Management Interface (<code>Nm</code>), horizontal über die gesamte Breite aufgeteilt (grau hinterlegt).\n</li><li><code>:UdpNm</code>: Zwei nebeneinander platzierte, separate Instanzen des UDP-Netzwerkmanagements (<code>UdpNm</code>), die jeweils einem spezifischen UDP-NM-Cluster zugeordnet sind.\n</li><li><code>:SoAd</code>: Eine gemeinsame unterlagerte Instanz des Socket Adaptors (<code>SoAd</code>), horizontal über die gesamte Breite angeordnet.\n</li></ul>\n<p class=\"fig-p\">Schnittstellen oder Port-Symbole sind nicht explizit als Konnektoren eingezeichnet; die Interaktion erfolgt implizit über die vertikale Schichtung (<code>:Nm</code> kommuniziert nach unten mit beiden <code>:UdpNm</code>-Instanzen, beide <code>:UdpNm</code>-Instanzen kommunizieren nach unten mit <code>:SoAd</code>).</p>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Das Diagramm zeigt eine statische Instanzstruktur ohne Kontrollfluss-, Sequenz- oder Zeitinformationen. Aus der vertikalen Schichtung und Multi-Cluster-Konfiguration leitet sich folgendes Interaktionsmuster ab:</p>\n<ul class=\"fig-list\"><li>Zyklische NM-Nachrichten und Zustandstrigger des generischen <code>:Nm</code> werden clusterindividuell an die jeweils zuständige <code>:UdpNm</code>-Instanz weitergeleitet.\n</li><li>Beide <code>:UdpNm</code>-Instanzen steuern unabhängig voneinander das Senden und Empfangen von NM-Botschaften über Sockets der gemeinsamen <code>:SoAd</code>-Instanz.\n</li><li>Empfangene NM-Pakete aus <code>:SoAd</code> werden clusterbezogen der jeweiligen <code>:UdpNm</code>-Instanz zugestellt und an <code>:Nm</code> signalisiert.\n</li></ul>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normativ veranschaulicht das Diagramm die Skalierungseinschränkung des UdpNm-Moduls:</p>\n<ul class=\"fig-list\"><li>Pro NM-Cluster und Netzwerk existiert auf dem Steuergerät genau eine <code>:UdpNm</code>-Instanz (1:1-Zuordnung je Cluster/Netzwerk).\n</li><li>Eine ECU, die an mehrere UDP-NM-Cluster angebunden ist, erfordert mehrere parallele Instanzen von <code>UdpNm</code>.\n</li><li>Alle <code>UdpNm</code>-Instanzen teilen sich eine gemeinsame <code>:Nm</code>-Instanz auf höherer Ebene und eine gemeinsame <code>:SoAd</code>-Instanz zur UDP-Kommunikation. Entwickler müssen bei Multi-Channel-/Multi-Cluster-Konfigurationen die Kanal- und Socket-Zuordnung in den BSW-Modulbeschreibungen strikt trennen.\n</li></ul>"}], "trans": [{"from": "FIG-a3d5c1d0d3bbf749", "to": "FIG-9a33df7b242c05e5", "fr": "R4.0.3", "tr": "R4.1.3", "change": "redaktionell", "label": "redaktionell", "html": "<ul class=\"fig-list\"><li>Ergänzung eines UML-Diagrammrahmens mit Kopfbereichskennzeichnung <code>id AUTOSAR NM Stack over UDP</code>.\n</li></ul>"}, {"from": "FIG-9a33df7b242c05e5", "to": "FIG-7c689f44b87ae3c1", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
